import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import 'package:url_launcher/url_launcher.dart';
import '../state/app_state.dart';

class OrderDetailScreen extends StatefulWidget { final int orderId; const OrderDetailScreen({super.key, required this.orderId}); @override State<OrderDetailScreen> createState() => _OrderDetailScreenState(); }
class _OrderDetailScreenState extends State<OrderDetailScreen> {
  late Future<dynamic> future;
  @override void initState() { super.initState(); future = context.read<AppState>().api.get('orders/${widget.orderId}'); }
  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Sipariş detayı')), body: FutureBuilder<dynamic>(future: future, builder: (_, snapshot) { if (snapshot.connectionState != ConnectionState.done) return const Center(child: CircularProgressIndicator()); if (snapshot.hasError) return Center(child: Text('${snapshot.error}')); final payload = snapshot.data is Map ? snapshot.data as Map : const {}; final order = payload['data'] is Map ? payload['data'] as Map : const {}; final items = ((order['items'] as List?) ?? (order['products'] as List?) ?? const []).whereType<Map>().toList(); final tracking = '${order['tracking_url'] ?? order['cargo_tracking_url'] ?? ''}'; final orderStatus = '${order['status_label'] ?? order['status'] ?? ''}'.toLowerCase(); return ListView(padding: const EdgeInsets.all(18), children: [Text('#${order['reference'] ?? order['order_reference'] ?? order['id_order'] ?? ''}', style: const TextStyle(fontSize: 24, fontWeight: FontWeight.w800)), const SizedBox(height: 8), Text('${order['status_label'] ?? order['status'] ?? ''}'), if (tracking.isNotEmpty) Padding(padding: const EdgeInsets.only(top: 16), child: OutlinedButton.icon(onPressed: () async { final uri = Uri.tryParse(tracking); if (uri != null) await launchUrl(uri, mode: LaunchMode.externalApplication); }, icon: const Icon(Icons.local_shipping_outlined), label: Text('${order['cargo_name'] ?? 'Kargo takibi'}'))), const Divider(height: 30), ...items.map((item) => ListTile(title: Text('${item['product_name'] ?? item['name'] ?? ''}'), subtitle: Text('${item['variation_label'] ?? ''} · ${item['quantity'] ?? item['qty'] ?? 1} adet'), trailing: Text('${item['total_formatted'] ?? item['total'] ?? item['price_formatted'] ?? ''}'))), const Divider(height: 30), _row('Toplam', order['total_formatted'] ?? order['total']), if (orderStatus.contains('bekle') || orderStatus.contains('pending')) OutlinedButton(onPressed: () => _request('cancel', 'İptal talebi nedeni'), child: const Text('İptal talebi oluştur')), if (orderStatus.contains('teslim') || orderStatus.contains('delivered')) OutlinedButton(onPressed: () => _request('return', 'İade talebi nedeni'), child: const Text('İade talebi oluştur')), OutlinedButton(onPressed: () => _request('message', 'Sipariş hakkında mesaj'), child: const Text('Sipariş hakkında soru sor'))]); }));
  Future<void> _request(String action, String title) async { final controller = TextEditingController(); final message = await showDialog<String>(context: context, builder: (_) => AlertDialog(title: Text(title), content: TextField(controller: controller, maxLines: 4, decoration: const InputDecoration(hintText: 'Mesajınızı yazın')), actions: [TextButton(onPressed: () => Navigator.pop(context), child: const Text('Vazgeç')), FilledButton(onPressed: () => Navigator.pop(context, controller.text.trim()), child: const Text('Gönder'))])); if (message == null || message.isEmpty || !mounted) return; try { final result = action == 'message' ? await context.read<AppState>().api.post('messages/${widget.orderId}', body: {'message': message}) : await context.read<AppState>().api.post('orders/${widget.orderId}/$action', body: {'message': message}); if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('${result['message'] ?? 'İşlem gönderildi'}'))); } catch (error) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text('$error'))); } }
  Widget _row(String label, dynamic value) => Row(mainAxisAlignment: MainAxisAlignment.spaceBetween, children: [Text(label, style: const TextStyle(fontWeight: FontWeight.w800)), Text('$value', style: const TextStyle(fontWeight: FontWeight.w900))]);
}
